#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {
        cout << "先搭妈妈那一半：" << name << endl;
    }
    virtual ~Cat() {
        cout << "后拆妈妈那一半：" << name << endl;
    }
};

class Kitten : public Cat {
    int fish;
public:
    Kitten(string n, int f) : Cat(n), fish(f) {
        cout << "再搭小猫那一半：" << name << endl;
    }
    ~Kitten() {
        cout << "先拆小猫那一半：" << name << "，还回 " << fish << " 条" << endl;
    }
};

int main() {
    int f = 0;
    cin >> f;

    Cat* p = new Kitten("{name}", f);
    delete p;
    return 0;
}
